      message.stopReason == StopReason.aborted) {
    return EmptyCompletionVerdict.abortedOrError;
  }
  if (_turnCarriesPartialContent(turnHistory, message)) {
    return EmptyCompletionVerdict.emptyAfterPartial;
  }
  return EmptyCompletionVerdict.cleanEmpty;
}

/// Whether the turn window of [turnHistory] (messages after the last user
/// message, excluding [message] itself) carries partial-content evidence:
/// actionable assistant content, tool activity, or a truncation signal.
bool _turnCarriesPartialContent(
  List<Message> turnHistory,
  AssistantMessage message,
) {
  if (_carriesTruncationSignal(message)) return true;
  var sawMessage = false;
  for (final entry in turnHistory.reversed) {
    if (!sawMessage && identical(entry, message)) {
      sawMessage = true;
      continue;
    }
    if (entry is UserMessage) {
      // gh-1603: the loop's own continuation nudge rides mid-turn and must
      // not reset the partial-content window — a nudged retry stays a
      // hiccup. A real user message ends the window.
      if (isContinuationNudgeMessage(entry)) continue;
      break;
    }
    switch (entry) {
      case AssistantMessage():
        if (_assistantEntryCarriesPartial(entry)) return true;
      case ToolResultMessage():
        // Tool activity: the turn did real work before going blank.
        return true;
      default:
        break;
    }
  }
  return false;
}

/// Whether one retained assistant entry in the turn window carries
/// partial-content evidence: actionable content, or a truncation signal.
bool _assistantEntryCarriesPartial(AssistantMessage entry) =>
    !isEmptyAssistantCompletion(entry) || _carriesTruncationSignal(entry);

/// A truncation signal on an assistant message: the token-limit cut, or the
/// tolerated silent truncation (a provider closed the stream without a
/// finish reason — the message is flagged with an errorMessage while keeping
/// a natural `stop`, see the openai-completions adapter).
bool _carriesTruncationSignal(AssistantMessage message) {
  if (message.stopReason == StopReason.length) return true;
  return message.stopReason == StopReason.stop && message.errorMessage != null;
}

/// Backoff before empty-hiccup retry [attempt] (0-based): exponential from
/// [baseDelay], capped at [maxBackoff] — the same shape as the model-roles
/// retry policy (`retry.baseDelayMs`/`retry.maxBackoffMs`), deterministic so
/// tests can pin the sequence (gh-1577 UT-4).
Duration emptyHiccupBackoffFor({
  required int attempt,
  required Duration baseDelay,
  required Duration maxBackoff,
}) {
  var ms = baseDelay.inMilliseconds * (1 << attempt.clamp(0, 20));
  if (ms > maxBackoff.inMilliseconds) ms = maxBackoff.inMilliseconds;
  return Duration(milliseconds: ms);
}

/// The loud exhaustion verdict (gh-1577 AC4): names the hiccup, the retry
/// count, the total attempt count, and the last stop reason. Surfaced as a
/// run error (`StopReason.error`) so the headless exit-code switch maps it
/// to non-zero and the interactive mode prints it and returns to the prompt.
String emptyHiccupExhaustedError({
  required int retryCount,
  required int attempts,
  required StopReason lastStopReason,
}) {
  return 'empty completion after partial content: the model returned no '
      'text and no tool calls in $attempts attempts '
      '($retryCount retries, last stop reason: ${lastStopReason.name}). '
      'The run stopped instead of settling an empty answer — repeat or '
      'rephrase the request.';
}

      context: context,
      reliefUsed: reliefUsed,
      retried: false,
      terminal: null,
    );
  }
  if (_reliefAvailable(reliefUsed, config)) {
    try {
      final relieved = await config.overWindowRelief!(context.messages);
      if (_isCancelRequested(cancelToken)) {
        // Issue #1085: the relief tokens are linked to the run token —
        // a USER abort mid-relief cancels the compaction and lands
        // here. The run must end aborted, NOT with the guard error:
        // the guard error re-arms the host's auto-continuation funnel,
        // which would silently resume the task the user just stopped.
        return (
          context: context,
          reliefUsed: true,
          retried: false,
          terminal: await _abortedTurn(context, config, emit),
        );
      }
      if (relieved != null) {
        // The relieved transcript becomes the loop's live context:
        // the retried request is built from it and every later turn
        // rides it (the tuple return hands it back to the host).
        return (
          context: Context(
            systemPrompt: context.systemPrompt,
            messages: relieved,
            tools: context.tools,
          ),
          reliefUsed: true,
          retried: true,
          terminal: null,
        );
      }
    } catch (_) {
      // A failed relief = no relief; the error below is the answer —
      // unless the failure WAS a cancellation (user abort mid-relief,
      // issue #1085): that must surface as aborted, never as the
      // guard error.
      if (_isCancelRequested(cancelToken)) {
        return (
          context: context,
          reliefUsed: true,
          retried: false,
          terminal: await _abortedTurn(context, config, emit),
        );
      }
    }
  }
  // gh-241 follow-up #5d (D5 — owner live test round 5): in the
  // soft-window regime the configured window is below what EVERY request
  // carries (fixed overhead + reserve); relief freed nothing; the
  // provider is the real limit — it accepted 108–123 % requests all
  // along. Stopping here ended a read-only turn in `stop=error`, exit 1:
  // an unsent request is worse than a slightly over one. The request
  // goes out as is.
  if (sendAnyway) {
    return (context: context, reliefUsed: true, retried: false, terminal: null);
  }
  return (
    context: context,
    reliefUsed: true,
    retried: false,
    terminal: (
      await _finishWithoutStream(
        context,
        emit,
        _terminalMessage(
          config.model,
          StopReason.error,
          '$contextWindowExhaustedMarker: the outgoing context is '
          '~$tokens tokens, '
          'the ${config.model.id} effective window is $window. The request '
          'was not sent. Auto-compaction runs next; if it keeps failing, '
          'run /compact or start a fresh session.',
        ),
      ),
      context,
    ),
  );
}

/// Whether the host's one-shot over-window relief is still on the table.
bool _reliefAvailable(bool reliefUsed, AgentLoopConfig config) =>
    !reliefUsed && config.overWindowRelief != null;

/// Whether the run was cancelled before its request went out.
bool _isCancelRequested(CancelToken? cancelToken) =>
    cancelToken != null && cancelToken.isCancelled;

/// The already-cancelled turn: no request leaves the loop.
Future<(AssistantMessage, Context)> _abortedTurn(
  Context context,
  AgentLoopConfig config,
  AgentEventSink emit,
) async {
  return (
    await _finishWithoutStream(
      context,
      emit,
      _terminalMessage(config.model, StopReason.aborted, 'Operation aborted'),
    ),
    context,
  );
}

/// A provider/runtime error thrown by the stream call itself becomes an
/// error turn, not a crash.
Future<(AssistantMessage, Context)> _providerErrorTurn(
  Context context,
  AgentLoopConfig config,
  AgentEventSink emit,
  Object error,
) async {
  return (
    await _finishWithoutStream(
      context,
      emit,
      _terminalMessage(config.model, StopReason.error, '$error'),
    ),
    context,
  );
}

/// Builds the synthetic error turn for a provider stream that closed
/// without any terminal event (provider bug): keep the streamed partial
/// when one landed, otherwise synthesize an empty error message.
AssistantMessage _streamEndedWithoutTerminal(
  AgentLoopConfig config,
  AssistantMessage? partial,
) {
  const errorText = 'Provider stream ended without a terminal event';
  return (partial ??
          _terminalMessage(config.model, StopReason.error, errorText))
      .copyWith(stopReason: StopReason.error, errorMessage: errorText);
}

